import React from 'react';
import {
  Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, Bot, CalendarDays, Check,
  CheckCheck, CheckCircle2, CircleDollarSign, Clock3, Download, FileText, Filter,
  Gauge, ImagePlus, LoaderCircle, LockKeyhole, Mail, MessageCircle, MoreHorizontal,
  Pencil, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, Sparkles, Trash2,
  UserCheck, UserPlus, UserRound, Users, WalletCards, X, XCircle
} from 'lucide-react';
import { Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { api, downloadFile } from './lib/api.js';
import { Avatar, Button, EmptyState, ErrorBanner, InputField, Modal, PageHeader, SearchBox, SelectField, StatCard, StatusPill, Table, TextAreaField } from './components.jsx';
import { LiveMeetingsPage } from './live.jsx';

const money = value => `PKR ${Number(value || 0).toLocaleString('en-PK',{maximumFractionDigits:0})}`;
const dateText = value => value ? new Date(value).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}) : '—';
const timeText = value => value ? new Date(value).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}) : '—';
const initials = value => String(value||'').trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
function useLoad(loader, deps=[]) {
  const [data,setData]=React.useState(null);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');
  const reload=React.useCallback(async()=>{setLoading(true);setError('');try{const result=await loader();setData(result);}catch(err){setError(err.message);}finally{setLoading(false);}},deps);
  React.useEffect(()=>{reload();},[reload]);
  return {data,setData,loading,error,reload,setError};
}
function CopyValue({ value, label='Copy' }) { const [copied,setCopied]=React.useState(false); return <button className="btn btn-secondary btn-sm" type="button" onClick={async()=>{try{await navigator.clipboard.writeText(String(value));setCopied(true);setTimeout(()=>setCopied(false),1800);}catch{window.prompt('Copy this value',String(value));}}}>{copied?<Check size={14}/>:<FileText size={14}/>} {copied?'Copied':label}</button>; }
function InlineNotice({ children, tone='info' }) { return <div className={`inline-notice notice-${tone}`}>{children}</div>; }
function LoadingRows() { return <div className="table-skeleton"><div/><div/><div/><div/></div>; }

export function PageContent({page,user,onUserUpdate,onNavigate,showToast}) {
  switch(page) {
    case 'dashboard': return <DashboardPage user={user} onNavigate={onNavigate} showToast={showToast}/>;
    case 'employees': return <DirectoryPage user={user} showToast={showToast}/>;
    case 'users': return <UserManagementPage showToast={showToast}/>;
    case 'attendance': return <AttendancePage user={user} showToast={showToast}/>;
    case 'leave': return <LeavePage user={user} showToast={showToast}/>;
    case 'payroll': return <PayrollPage user={user} showToast={showToast}/>;
    case 'announcements': return <AnnouncementsPage user={user} showToast={showToast}/>;
    case 'live': return <LiveMeetingsPage user={user} showToast={showToast}/>;
    case 'organization': return <OrganizationPage showToast={showToast}/>;
    case 'audit': return <AuditPage/>;
    case 'profile': return <ProfilePage user={user} onUserUpdate={onUserUpdate} showToast={showToast}/>;
    case 'ai': return <AIPage user={user} showToast={showToast}/>;
    default: return <DashboardPage user={user} onNavigate={onNavigate} showToast={showToast}/>;
  }
}

function DashboardPage({user,onNavigate,showToast}) {
 const {data,loading,error,reload}=useLoad(()=>api('/dashboard'));
 const role=user.role;
 return <>
  <PageHeader eyebrow={role==='employee'?'YOUR WORKSPACE':'PEOPLE OPERATIONS'} title={role==='employee'?`Good ${dayPart()}, ${firstName(user)}.`:`${greeting()}, ${firstName(user)}.`} description={role==='employee'?'Your workday, leave and payslips in one view.':'Here is what is happening across your people workspace.'} actions={<><span className="date-chip"><CalendarDays size={15}/>{new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span><Button variant="secondary" onClick={reload}><RefreshCw size={15}/> Refresh</Button></>}/>
  {error?<ErrorBanner message={error} onRetry={reload}/>:null}
  {loading?<DashboardSkeleton/>:data?role==='employee'?<EmployeeDashboard data={data} user={user} onNavigate={onNavigate} showToast={showToast}/>:<StaffDashboard data={data} user={user} role={role} onNavigate={onNavigate}/>:null}
 </>;
}
function DashboardSkeleton(){return <><div className="stats-grid"><div className="skeleton-card"/><div className="skeleton-card"/><div className="skeleton-card"/><div className="skeleton-card"/></div><div className="dashboard-grid"><div className="skeleton-panel"/><div className="skeleton-panel"/></div></>}
function StaffDashboard({data,user,role,onNavigate}) {
 const isAdmin=role==='admin';
 const cards=[{label:'Active headcount',value:data.activeHeadcount??0,icon:Users,tone:'teal',note:`${data.totalEmployees??0} employee records`},{label:'Pending leave requests',value:data.pendingLeaveRequests??0,icon:CalendarDays,tone:'violet',note:'Waiting for review'},{label:'Late today',value:data.attendanceCounts?.late??0,icon:Clock3,tone:'amber',note:'Based on recorded check-ins'},{label:isAdmin?'Average basic salary':'Pending corrections',value:isAdmin?money(data.averageSalary):data.pendingAttendanceCorrections??0,icon:isAdmin?CircleDollarSign:FileText,tone:'blue',note:isAdmin?'Active employee records':'Attendance review queue'}];
 const chartData=(data.departmentStats||[]).slice(0,7).map(item=>({name:item.department==='unassigned'?'Unassigned':item.department,headcount:item.headcount}));
 return <>
  <div className="stats-grid">{cards.map(card=><StatCard key={card.label} {...card}/>)}</div>
  <div className="dashboard-grid dashboard-grid-main">
   <section className="panel chart-panel"><div className="panel-heading"><div><h2>Team distribution</h2><p>Active employees by department</p></div><button className="text-action" onClick={()=>onNavigate('employees')}>View directory <ArrowRight size={14}/></button></div>
   {chartData.length?<div className="chart-area"><ResponsiveContainer width="100%" height={260}><BarChart data={chartData} margin={{top:8,right:10,left:-22,bottom:0}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="name" tick={{fontSize:13,fill:'var(--chart-muted)'}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fontSize:13,fill:'var(--chart-muted)'}} axisLine={false} tickLine={false}/><Tooltip cursor={{fill:'var(--chart-hover)'}} contentStyle={{border:'1px solid var(--line)',borderRadius:12,fontSize:14,background:'var(--panel)',color:'var(--ink)'}}/><Bar dataKey="headcount" name="Employees" fill="#0d9488" radius={[5,5,0,0]} maxBarSize={42}/></BarChart></ResponsiveContainer></div>:<EmptyState icon={Users} title="Your people data starts here" description="Add employees to see how your team is distributed across departments." action={<Button size="sm" onClick={()=>onNavigate('employees')}><Plus size={14}/> Add employee</Button>}/>}
   <div className="chart-footer"><span><i className="legend-dot legend-teal"/> Active employees</span><span>{data.activeHeadcount??0} people</span></div></section>
   <section className="panel quick-panel"><div className="panel-heading"><div><h2>Quick actions</h2><p>Move the everyday work forward</p></div><span className="panel-heading-icon"><Sparkles size={17}/></span></div>
    <div className="quick-actions">{(isAdmin?[['employees','Add an employee','Create a staff profile',UserPlus,'teal'],['users','Create an HR account','Grant HR workspace access',ShieldCheck,'violet'],['leave','Review leave requests','Keep approvals moving',CalendarDays,'amber'],['payroll','Prepare payroll','Create this month’s draft',WalletCards,'blue']]:[['employees','Add an employee','Create a staff profile',UserPlus,'teal'],['leave','Review leave requests','Check the approval inbox',CalendarDays,'amber'],['attendance','Attendance overview','Review saved check-ins',Clock3,'blue'],['announcements','Post an announcement','Share an update with staff',MessageCircle,'violet']]).map(([target,title,description,Icon,tone])=><button key={title} className="quick-action" onClick={()=>onNavigate(target)}><span className={`quick-icon tone-${tone}`}><Icon size={17}/></span><span><strong>{title}</strong><small>{description}</small></span><ArrowUpRight size={15} className="quick-arrow"/></button>)}</div>
   </section>
  </div>
  <div className="dashboard-grid dashboard-grid-lower">
   <section className="panel data-panel"><div className="panel-heading"><div><h2>Today's attendance</h2><p>Checked-in employees · {new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'})}</p></div><button className="text-action" onClick={()=>onNavigate('attendance')}>Open attendance <ArrowRight size={14}/></button></div>
    <div className="attendance-metrics">{[['Present',data.attendanceCounts?.present??0,'teal'],['Late',data.attendanceCounts?.late??0,'amber'],['Half day',data.attendanceCounts?.halfDay??0,'violet'],['Checked out',data.attendanceCounts?.checkedOut??0,'blue']].map(([label,value,tone])=><div key={label} className="attendance-metric"><div><span className={`metric-dot tone-${tone}`}/><span>{label}</span></div><strong>{value}</strong></div>)}</div>
    <p className="muted-small">Counts include actual attendance records only. Missing check-ins are not stored as invented absences.</p>
   </section>
   <section className="panel data-panel"><div className="panel-heading"><div><h2>{isAdmin?'Latest payroll run':'Payroll workspace'}</h2><p>{isAdmin?'Finalized payroll snapshot':'Drafts awaiting Admin finalization'}</p></div><button className="text-action" onClick={()=>onNavigate('payroll')}>View payroll <ArrowRight size={14}/></button></div>
    {data.latestPayroll?<div className="payroll-highlight"><span className="payroll-highlight-icon"><WalletCards size={20}/></span><div><span className="muted-small">{data.latestPayroll.period} · Finalized</span><strong>{money(data.latestPayroll.summary?.netTotal)}</strong><small>{data.latestPayroll.summary?.employeeCount??0} payslips included</small></div><StatusPill status="finalized"/></div>:<EmptyState icon={WalletCards} title="No finalized payroll yet" description="Payroll totals will appear here after an Admin finalizes a draft." action={<Button size="sm" variant="secondary" onClick={()=>onNavigate('payroll')}>Open payroll <ArrowRight size={14}/></Button>}/>}
   </section>
  </div>
  {role==='admin'?<section className="panel recent-activity-panel"><div className="panel-heading"><div><h2>Recent admin activity</h2><p>A transparent view of important workspace actions</p></div><button className="text-action" onClick={()=>onNavigate('audit')}>See audit trail <ArrowRight size={14}/></button></div>{data.recentAudit?.length?<div className="activity-list">{data.recentAudit.map(item=><div key={item._id} className="activity-row"><span className="activity-mark"><ShieldCheck size={15}/></span><div><strong>{humanize(item.action)}</strong><p>{item.actor?.profile?.fullName||'System'} · {item.entity}</p></div><time>{relativeDate(item.createdAt)}</time></div>)}</div>:<EmptyState icon={Activity} title="No recent activity" description="Important administrative actions will be recorded here."/>}</section>:null}
 </>;
}
function EmployeeDashboard({data,onNavigate,showToast}) {
 const attendance=data.todayAttendance;const hasCheckedIn=Boolean(attendance?.checkIn);const hasCheckedOut=Boolean(attendance?.checkOut);const [busy,setBusy]=React.useState(false);
 async function attendanceAction(){setBusy(true);try{const result=await api(`/attendance/${hasCheckedIn?'check-out':'check-in'}`,{method:'POST',body:{}});showToast(result.message||'Attendance updated.');window.location.reload();}catch(err){showToast(err.message,'error');setBusy(false);}}
 const workingHours=Number(data.weekHours||0);const donut=[{name:'Worked',value:Math.min(workingHours,40)},{name:'Remaining',value:Math.max(0,40-Math.min(workingHours,40))}];
 const quotas=data.leaveQuotas||{annual:14,sick:8,casual:10};
 return <>
  <div className="employee-hero"><div className="employee-hero-copy"><span className="hero-label"><span/> YOUR DAY AT A GLANCE</span><h2>{attendance?hasCheckedOut?'Your workday is wrapped up.':`You're checked in${attendance.status==='late'?' — arriving a little late':''}.`:'Ready when you are.'}</h2><p>{attendance?hasCheckedOut?`You recorded ${attendance.hoursWorked||0} hours today. Nice work.`:'Keep your check-in and check-out up to date for accurate attendance.':'Check in when you start, and check out when your workday ends.'}</p><div className="hero-actions"><Button loading={busy} disabled={hasCheckedOut} onClick={attendanceAction}>{hasCheckedIn?'Check out':'Check in'} <ArrowUpRight size={15}/></Button><span className="hero-time"><Clock3 size={15}/>{hasCheckedIn?`In at ${timeText(attendance.checkIn)}`:'No check-in recorded yet'}</span></div></div><div className="hero-clock"><div className="clock-face"><span>{new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',hour12:false})}</span><small>{new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'})}</small><i/></div><div className="clock-caption"><span className={hasCheckedIn?'clock-live':'clock-idle'}/>{hasCheckedIn?(hasCheckedOut?'Shift complete':'Shift in progress'):'Not checked in'}</div></div></div>
  <div className="stats-grid employee-stats"><StatCard label="Hours this week" value={`${workingHours.toFixed(1)}h`} icon={Clock3} tone="teal" note="40-hour reference"/><StatCard label="Late arrivals" value={data.lateCount??0} icon={Activity} tone="amber" note="Recorded this year"/><StatCard label="Pending leave" value={data.pendingLeaveRequests??0} icon={CalendarDays} tone="violet" note="Requests awaiting review"/><StatCard label="Notifications" value={data.unreadNotifications??0} icon={MessageCircle} tone="blue" note="Unread updates"/></div>
  <div className="dashboard-grid dashboard-grid-main"><section className="panel chart-panel"><div className="panel-heading"><div><h2>Your weekly rhythm</h2><p>Hours logged compared with a 40-hour reference</p></div><span className="tag tag-soft">This week</span></div><div className="hours-chart-wrap"><div className="hours-ring"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={donut} dataKey="value" cx="50%" cy="50%" innerRadius={65} outerRadius={78} startAngle={90} endAngle={-270} stroke="none">{donut.map((entry,index)=><Cell key={index} fill={index===0?'#0d9488':'var(--chart-track)'}/>)}</Pie></PieChart></ResponsiveContainer><div className="hours-ring-label"><strong>{workingHours.toFixed(1)}<small>h</small></strong><span>of 40 hours</span></div></div><div className="hours-summary"><span className="eyebrow">WEEKLY HOURS</span><h3>{Math.round(Math.min(100,workingHours/40*100))}% <small>of reference</small></h3><p>{workingHours>=40?'You have met the 40-hour reference.':`${(40-workingHours).toFixed(1)} hours remaining to the weekly reference.`}</p><div className="progress-track"><span style={{width:`${Math.min(100,workingHours/40*100)}%`}}/></div><button className="text-action" onClick={()=>onNavigate('attendance')}>View attendance history <ArrowRight size={14}/></button></div></div></section>
  <section className="panel quick-panel"><div className="panel-heading"><div><h2>Leave balance</h2><p>Your approved leave usage this year</p></div><span className="panel-heading-icon"><CalendarDays size={17}/></span></div><div className="leave-balance-list">{[['annual','Annual leave',quotas.annual||14,'teal'],['sick','Sick leave',quotas.sick||8,'violet'],['casual','Casual leave',quotas.casual||10,'amber']].map(([key,label,quota,tone])=>{const used=Number(data.leaveUsed||0);const usedForType=Number(data.leaveBalances?.[key]?.used||0);return <div className="leave-balance-item" key={key}><div className="leave-balance-top"><span>{label}</span><strong>{Math.max(0,Number(quota)-usedForType)} <small>left</small></strong></div><div className="progress-track"><span className={`progress-${tone}`} style={{width:`${Math.min(100,usedForType/Math.max(1,quota)*100)}%`}}/></div><small className="muted-small">{usedForType} of {quota} days used</small></div>})}</div><Button variant="secondary" block onClick={()=>onNavigate('leave')}>Apply for leave <ArrowRight size={14}/></Button></section></div>
  <div className="dashboard-grid dashboard-grid-lower"><section className="panel data-panel"><div className="panel-heading"><div><h2>Recent attendance</h2><p>Your latest saved records</p></div><button className="text-action" onClick={()=>onNavigate('attendance')}>All records <ArrowRight size={14}/></button></div>{data.attendanceRecent?.length?<div className="mini-record-list">{data.attendanceRecent.slice(0,5).map(a=><div key={a._id} className="mini-record-row"><div className="mini-record-date"><strong>{new Date(`${a.dayKey}T00:00:00`).getDate()}</strong><small>{new Date(`${a.dayKey}T00:00:00`).toLocaleDateString(undefined,{month:'short'})}</small></div><div className="mini-record-info"><strong>{dateText(`${a.dayKey}T00:00:00`)}</strong><small>{timeText(a.checkIn)} — {timeText(a.checkOut)}</small></div><span className="mini-record-hours">{a.hoursWorked?`${a.hoursWorked.toFixed(1)}h`:'—'}</span><StatusPill status={a.status}/></div>)}</div>:<EmptyState icon={Clock3} title="No attendance recorded yet" description="Your check-ins and check-outs will appear here."/>}</section><section className="panel data-panel"><div className="panel-heading"><div><h2>Latest payslip</h2><p>Most recent finalized payroll</p></div><button className="text-action" onClick={()=>onNavigate('payroll')}>My payslips <ArrowRight size={14}/></button></div>{data.latestPayslip?<div className="payslip-preview"><span className="payslip-icon"><FileText size={20}/></span><div><strong>{data.latestPayslip.period}</strong><small>Net pay</small><h3>{money(data.latestPayslip.breakdown?.net)}</h3></div><Button size="sm" variant="secondary" onClick={()=>downloadFile(`/payroll/payslips/${data.latestPayslip._id}/pdf`,`payslip-${data.latestPayslip.period}.pdf`).catch(e=>showToast(e.message,'error'))}><Download size={14}/></Button></div>:<EmptyState icon={WalletCards} title="Your payslips will appear here" description="Only finalized payrolls are visible to employees."/>}</section></div>
 </>;
}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening';}function dayPart(){const h=new Date().getHours();return h<12?'morning':h<17?'afternoon':'evening';}function firstName(user){return (user?.profile?.fullName||user?.username||'there').trim().split(/\s+/)[0];}
function humanize(value){return String(value||'Activity').replaceAll('.',' ').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function relativeDate(value){const diff=Math.max(0,Date.now()-new Date(value).getTime());if(diff<60000)return 'Just now';if(diff<3600000)return `${Math.floor(diff/60000)}m ago`;if(diff<86400000)return `${Math.floor(diff/3600000)}h ago`;return dateText(value);}
function downloadCredentialsCsv(rows){const headers=['employeeCode','email','username','temporaryPassword'];const escape=value=>`"${String(value??'').replaceAll('"','""')}"`;const csv=[headers.join(','),...rows.map(row=>headers.map(key=>escape(row[key])).join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='hcm-import-credentials.csv';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);}

function DirectoryPage({user,showToast}) {
 const [items,setItems]=React.useState([]);const [departments,setDepartments]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [search,setSearch]=React.useState('');const [status,setStatus]=React.useState('');const [modal,setModal]=React.useState(false);const [editing,setEditing]=React.useState(null);const [saving,setSaving]=React.useState(false);const [tempPassword,setTempPassword]=React.useState(null);const [form,setForm]=React.useState({fullName:'',email:'',username:'',employeeCode:'',department:'',designation:'',joiningDate:new Date().toISOString().slice(0,10),employmentStatus:'active',salary:'',phone:'',address:'',temporaryPassword:''});const [fieldErrors,setFieldErrors]=React.useState({});const [csvModal,setCsvModal]=React.useState(false);const [csvFile,setCsvFile]=React.useState(null);const [csvReport,setCsvReport]=React.useState(null);const [csvBusy,setCsvBusy]=React.useState(false);const [csvCredentials,setCsvCredentials]=React.useState(null);
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{const params=new URLSearchParams();if(search.trim())params.set('search',search.trim());if(status)params.set('status',status);params.set('limit','100');const [res,dept]=await Promise.all([api(`/employees?${params}`),api('/company/departments')]);setItems(res.items||[]);setDepartments(dept.items||[]);}catch(err){setError(err.message);}finally{setLoading(false);}},[search,status]);
 React.useEffect(()=>{load();},[load]);
 const startCreate=()=>{setEditing(null);setFieldErrors({});setForm({fullName:'',email:'',username:'',employeeCode:'',department:departments[0]?._id||'',designation:'',joiningDate:new Date().toISOString().slice(0,10),employmentStatus:'active',salary:'',phone:'',address:'',temporaryPassword:''});setModal(true);};
 const startEdit=(row)=>{setEditing(row);setFieldErrors({});setForm({fullName:row.user?.profile?.fullName||'',email:row.user?.email||'',username:row.user?.username||'',employeeCode:row.employeeCode||'',department:row.department?._id||'',designation:row.designation||'',joiningDate:row.joiningDate?new Date(row.joiningDate).toISOString().slice(0,10):'',employmentStatus:row.employmentStatus||'active',salary:String(row.salary??''),phone:row.user?.profile?.phone||'',address:row.user?.profile?.address||'',temporaryPassword:''});setModal(true);};
 const set=(key,value)=>{setForm(old=>({...old,[key]:value}));setFieldErrors(old=>({...old,[key]:''}));};
 async function submit(e){e.preventDefault();setSaving(true);setFieldErrors({});try{const body={...form,salary:Number(form.salary||0),department:form.department||null};if(editing){delete body.temporaryPassword;await api(`/employees/${editing._id}`,{method:'PATCH',body});showToast('Employee profile updated.');setModal(false);load();}else{const result=await api('/employees',{method:'POST',body});setModal(false);setTempPassword({password:result.temporaryPassword,name:result.user?.profile?.fullName||form.fullName,username:result.user?.username});showToast('Employee account created.');load();}}catch(err){if(err.details&&typeof err.details==='object'){setFieldErrors(err.details);setFieldErrors(prev=>({...prev,...err.details}));}setError(err.message);showToast(err.message,'error');}finally{setSaving(false);}}
 async function validateCsv(){if(!csvFile){showToast('Choose a CSV file first.','error');return;}setCsvBusy(true);setCsvReport(null);try{const formData=new FormData();formData.append('file',csvFile);const report=await api('/employees/import/dry-run',{method:'POST',body:formData});setCsvReport(report);if(report.error)showToast(report.error,'error');else showToast(`Validation complete: ${report.validCount} valid, ${report.invalidCount} invalid row(s).`,report.invalidCount?'info':'success');}catch(e){showToast(e.message,'error');}finally{setCsvBusy(false);}}
 async function importCsv(){if(!csvFile||!csvReport||csvReport.error||csvReport.invalidCount!==0||csvReport.validCount<1)return;setCsvBusy(true);try{const formData=new FormData();formData.append('file',csvFile);const result=await api('/employees/import',{method:'POST',body:formData});setCsvModal(false);setCsvCredentials(result.credentials||[]);showToast(`${result.importedCount} employees imported successfully.`);setCsvFile(null);setCsvReport(null);load();}catch(e){showToast(e.message,'error');}finally{setCsvBusy(false);}}
 async function toggleStatus(row){const disabling=row.user?.active!==false;const next=disabling?'inactive':'active';if(!window.confirm(`${disabling?'Deactivate':'Reactivate'} ${row.user?.profile?.fullName||row.employeeCode}?`))return;try{await api(`/employees/${row._id}/status`,{method:'PATCH',body:{employmentStatus:next,active:!disabling}});showToast(`Employee ${disabling?'deactivated':'reactivated'}.`);load();}catch(err){showToast(err.message,'error');}}
 const columns=[{key:'employee',label:'Employee',render:r=><div className="person-cell"><Avatar user={r.user}/><div><strong>{r.user?.profile?.fullName||'Unnamed employee'}</strong><small>{r.user?.email||'No email'}</small></div></div>},{key:'employeeCode',label:'Employee ID',render:r=><span className="code-chip">{r.employeeCode}</span>},{key:'department',label:'Department',render:r=><div className="stacked-cell"><span>{r.department?.name||'Unassigned'}</span><small>{r.designation||'No designation'}</small></div>},{key:'joiningDate',label:'Joined',render:r=>dateText(r.joiningDate)},{key:'salary',label:'Basic salary',align:'right',render:r=>money(r.salary)},{key:'status',label:'Status',render:r=><StatusPill status={r.user?.active===false?'inactive':r.employmentStatus}/>},{key:'actions',label:'',align:'right',render:r=><div className="row-actions"><button className="icon-button" title="Edit employee" onClick={()=>startEdit(r)}><Pencil size={15}/></button><button className="icon-button" title={r.user?.active===false?'Reactivate employee':'Deactivate employee'} onClick={()=>toggleStatus(r)}>{r.user?.active===false?<UserCheck size={15}/>:<LockKeyhole size={15}/>}</button></div>}];
 return <>
  <PageHeader eyebrow="PEOPLE OPERATIONS" title="People directory" description="One reliable place for the people behind your work." actions={<><Button variant="secondary" onClick={()=>{setCsvFile(null);setCsvReport(null);setCsvModal(true);}}><ArrowDownToLine size={15}/> Import CSV</Button><Button variant="secondary" onClick={()=>downloadFile('/employees/export.csv','hcm-employees.csv').catch(e=>showToast(e.message,'error'))}><Download size={15}/> Export CSV</Button><Button onClick={startCreate}><Plus size={16}/> Add employee</Button></>}/>
  <div className="directory-overview"><div className="directory-overview-icon"><Users size={20}/></div><div><strong>{items.length} people in view</strong><span>Profiles are saved to MongoDB. Employee login access is created with each new profile.</span></div><span className="directory-overview-tag"><CheckCircle2 size={14}/> Directory synced</span></div>
  <section className="panel table-panel"><div className="table-toolbar"><div><h2>All employees</h2><p>Search, review and manage employee records</p></div><div className="toolbar-controls"><SearchBox value={search} onChange={setSearch} placeholder="Search name, email, code…"/><select className="input filter-select" value={status} onChange={e=>setStatus(e.target.value)} aria-label="Filter employment status"><option value="">All statuses</option><option value="active">Active</option><option value="on_leave">On leave</option><option value="inactive">Inactive</option><option value="terminated">Terminated</option></select><button className="icon-button" onClick={load} title="Refresh directory"><RefreshCw size={16}/></button></div></div>
  {error?<ErrorBanner message={error} onRetry={load}/>:null}<Table columns={columns} rows={items} loading={loading} emptyTitle="No employees found" emptyDescription={search||status?'Try clearing the search or status filter.':'Create your first employee to start building your directory.'} rowKey={r=>r._id}/></section>
  {modal?<Modal title={editing?'Edit employee profile':'Create employee account'} subtitle={editing?'Update professional information and access details.':'A login account and employee profile will be created together.'} onClose={()=>setModal(false)} size="lg"><form onSubmit={submit} className="modal-form"><div className="form-grid"><InputField label="Full name" required value={form.fullName} onChange={e=>set('fullName',e.target.value)} error={fieldErrors.fullName}/><InputField label="Email address" type="email" required value={form.email} onChange={e=>set('email',e.target.value)} error={fieldErrors.email}/><InputField label="Username" required value={form.username} onChange={e=>set('username',e.target.value)} hint="3–30 letters, numbers, . _ -" error={fieldErrors.username}/><InputField label="Employee code" required value={form.employeeCode} onChange={e=>set('employeeCode',e.target.value)} error={fieldErrors.employeeCode}/><SelectField label="Department" value={form.department} onChange={e=>set('department',e.target.value)}><option value="">Unassigned</option>{departments.map(d=><option key={d._id} value={d._id}>{d.name}</option>)}</SelectField><InputField label="Designation" value={form.designation} onChange={e=>set('designation',e.target.value)}/><InputField label="Joining date" type="date" required value={form.joiningDate} onChange={e=>set('joiningDate',e.target.value)} error={fieldErrors.joiningDate}/><InputField label="Basic monthly salary (PKR)" type="number" min="0" required value={form.salary} onChange={e=>set('salary',e.target.value)} error={fieldErrors.salary}/><InputField label="Phone number" value={form.phone} onChange={e=>set('phone',e.target.value)}/><SelectField label="Employment status" value={form.employmentStatus} onChange={e=>set('employmentStatus',e.target.value)}><option value="active">Active</option><option value="on_leave">On leave</option><option value="inactive">Inactive</option><option value="terminated">Terminated</option></SelectField><InputField label="Emergency contact" value={form.emergencyContact||''} onChange={e=>set('emergencyContact',e.target.value)}/><InputField label="Address" value={form.address} onChange={e=>set('address',e.target.value)}/>{!editing?<InputField label="Temporary password (optional)" type="password" value={form.temporaryPassword} onChange={e=>set('temporaryPassword',e.target.value)} hint="Leave blank to generate a secure password." error={fieldErrors.temporaryPassword}/>:null}</div><div className="modal-form-footer"><span className="muted-small"><ShieldCheck size={14}/> {editing?'Changes are validated by the server.':'The employee must change their temporary password at first sign-in.'}</span><div><Button type="button" variant="secondary" onClick={()=>setModal(false)}>Cancel</Button><Button type="submit" loading={saving}>{editing?'Save changes':'Create employee'}</Button></div></div></form></Modal>:null}
  {csvModal?<Modal title="Import employees from CSV" subtitle="Validate every row first. No employee accounts are created during dry-run validation." onClose={()=>setCsvModal(false)} size="lg"><div className="csv-import-flow"><div className="csv-template-note"><FileText size={19}/><div><strong>Required CSV columns</strong><p>employeeCode, fullName, username, email, department, designation, joiningDate, basicSalary</p><small>Use the exact active department name. joiningDate must be YYYY-MM-DD, and basicSalary must be greater than zero.</small></div></div><label className="field csv-file-field"><span className="field-label">Choose CSV file (maximum 5 MB, up to 500 rows)</span><input className="input" type="file" accept=".csv,text/csv" onChange={e=>{setCsvFile(e.target.files?.[0]||null);setCsvReport(null);}}/><span className="field-hint">No data is created until every row passes validation and you confirm the import.</span></label><div className="csv-actions"><Button variant="secondary" onClick={validateCsv} loading={csvBusy} disabled={!csvFile}><ShieldCheck size={15}/> Validate CSV (dry run)</Button>{csvReport&&!csvReport.error&&csvReport.invalidCount===0&&csvReport.validCount>0?<Button onClick={importCsv} loading={csvBusy}><Check size={15}/> Import {csvReport.validCount} rows</Button>:null}</div>{csvReport?<div className="csv-report"><div className="csv-report-summary"><div><strong>{csvReport.validCount||0}</strong><span>Valid rows</span></div><div><strong>{csvReport.invalidCount||0}</strong><span>Invalid rows</span></div><StatusPill status={csvReport.error?'rejected':csvReport.invalidCount?'pending':'approved'}/></div>{csvReport.error?<InlineNotice>{csvReport.error}</InlineNotice>:null}{csvReport.rows?.filter(r=>!r.valid).length?<div className="csv-error-list">{csvReport.rows.filter(r=>!r.valid).map(row=><div key={row.row}><strong>Row {row.row}</strong><ul>{row.errors.map((e,i)=><li key={i}><b>{e.field}:</b> {e.reason}</li>)}</ul></div>)}</div>:csvReport.validCount>0?<InlineNotice><CheckCircle2 size={15}/> All rows passed dry-run validation. Import is now enabled. Each employee receives a temporary password that must be changed at first sign-in.</InlineNotice>:null}</div>:null}<div className="modal-form-footer"><span className="muted-small">Existing email, username or employee-code duplicates will block the import.</span><div><Button type="button" variant="secondary" onClick={()=>setCsvModal(false)}>Close</Button></div></div></div></Modal>:null}
  {csvCredentials?<Modal title="CSV import complete" subtitle="These temporary passwords are shown once. Download the credentials now and share them securely." onClose={()=>setCsvCredentials(null)} size="lg"><div className="csv-credentials-header"><div><CheckCircle2 size={20}/><strong>{csvCredentials.length} employee accounts created</strong></div><Button onClick={()=>downloadCredentialsCsv(csvCredentials)}><Download size={15}/> Download credentials CSV</Button></div><div className="csv-credentials-list">{csvCredentials.map(item=><div key={String(item.userId)}><div><strong>{item.employeeCode}</strong><small>{item.email} · @{item.username}</small></div><code>{item.temporaryPassword}</code><CopyValue value={item.temporaryPassword}/></div>)}</div><div className="modal-form-footer"><span className="muted-small">These credentials are not saved in plaintext in the database.</span><Button onClick={()=>setCsvCredentials(null)}>Done</Button></div></Modal>:null}
  {tempPassword?<Modal title="Employee account created" subtitle="Copy this temporary password now. It will not be shown again." onClose={()=>setTempPassword(null)}><div className="credential-card"><div className="credential-symbol"><CheckCircle2 size={23}/></div><strong>{tempPassword.name}</strong><span>Username: <b>{tempPassword.username}</b></span><div className="credential-value">{tempPassword.password}<CopyValue value={tempPassword.password}/></div><p>The employee must set a new password on first login. Share these credentials securely.</p><Button block onClick={()=>setTempPassword(null)}>Done</Button></div></Modal>:null}
 </>;
}

function UserManagementPage({showToast}) {
 const [items,setItems]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [query,setQuery]=React.useState('');const [modal,setModal]=React.useState(false);const [form,setForm]=React.useState({fullName:'',email:'',username:'',temporaryPassword:''});const [fieldErrors,setFieldErrors]=React.useState({});const [saving,setSaving]=React.useState(false);const [credential,setCredential]=React.useState(null);
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{const res=await api(`/users?limit=100${query?`&search=${encodeURIComponent(query)}`:''}`);setItems(res.items||[]);}catch(e){setError(e.message);}finally{setLoading(false);}},[query]);React.useEffect(()=>{load();},[load]);
 async function submit(e){e.preventDefault();setSaving(true);setFieldErrors({});try{const result=await api('/users/hr',{method:'POST',body:{...form,temporaryPassword:form.temporaryPassword||undefined}});setModal(false);setCredential({name:result.user.profile?.fullName,username:result.user.username,email:result.user.email,password:result.temporaryPassword});showToast('HR account created.');load();}catch(err){setError(err.message);if(err.details)setFieldErrors(err.details);showToast(err.message,'error');}finally{setSaving(false);}}
 async function toggle(user){const next=!user.active;if(!window.confirm(`${next?'Reactivate':'Deactivate'} ${user.profile?.fullName||user.username}?`))return;try{await api(`/users/${user._id||user.id}/status`,{method:'PATCH',body:{active:next}});showToast(`Account ${next?'reactivated':'deactivated'}.`);load();}catch(e){showToast(e.message,'error');}}
 async function reset(user){if(!window.confirm(`Reset the password for ${user.profile?.fullName||user.username}?`))return;try{const result=await api(`/users/${user._id||user.id}/reset-password`,{method:'POST',body:{}});setCredential({name:user.profile?.fullName,username:user.username,email:user.email,password:result.temporaryPassword});showToast('Temporary password generated.');}catch(e){showToast(e.message,'error');}}
 const columns=[{key:'name',label:'Account',render:u=><div className="person-cell"><Avatar user={u}/><div><strong>{u.profile?.fullName||u.username}</strong><small>{u.email}</small></div></div>},{key:'username',label:'Username',render:u=><span className="code-chip">{u.username}</span>},{key:'role',label:'Role',render:u=><span className="role-badge"><ShieldCheck size={13}/> {u.role==='admin'?'Administrator':'HR manager'}</span>},{key:'createdAt',label:'Created',render:u=>dateText(u.createdAt)},{key:'active',label:'Status',render:u=><StatusPill status={u.active?'active':'inactive'}/>},{key:'actions',label:'',align:'right',render:u=><div className="row-actions"><button className="icon-button" title="Reset password" onClick={()=>reset(u)}><LockKeyhole size={15}/></button><button className="icon-button" title={u.active?'Deactivate':'Reactivate'} onClick={()=>toggle(u)}>{u.active?<XCircle size={15}/>:<UserCheck size={15}/>}</button></div>}];
 return <><PageHeader eyebrow="ADMINISTRATION" title="Access management" description="Create HR accounts and control access to the people workspace." actions={<Button onClick={()=>{setForm({fullName:'',email:'',username:'',temporaryPassword:''});setFieldErrors({});setModal(true);}}><UserPlus size={16}/> Create HR account</Button>}/>
  <div className="notice-row"><InlineNotice><ShieldCheck size={16}/> Only Admin can create HR accounts. HR users can create employee accounts from the People directory.</InlineNotice></div>
  <section className="panel table-panel"><div className="table-toolbar"><div><h2>Privileged accounts</h2><p>Admin and HR accounts · passwords are never displayed after creation</p></div><div className="toolbar-controls"><SearchBox value={query} onChange={setQuery} placeholder="Search accounts…"/><button className="icon-button" onClick={load} title="Refresh accounts"><RefreshCw size={16}/></button></div></div>{error?<ErrorBanner message={error} onRetry={load}/>:null}<Table columns={columns} rows={items} loading={loading} emptyTitle="No privileged accounts yet" emptyDescription="The first Admin account was created during initial setup. Create HR accounts here." rowKey={u=>u._id||u.id}/></section>
 {modal?<Modal title="Create HR account" subtitle="A new HR user can manage employee operations but cannot create Admin accounts or finalize payroll." onClose={()=>setModal(false)}><form className="modal-form" onSubmit={submit}><InputField label="Full name" required value={form.fullName} onChange={e=>setForm({...form,fullName:e.target.value})} error={fieldErrors.fullName}/><InputField label="Email address" type="email" required value={form.email} onChange={e=>setForm({...form,email:e.target.value})} error={fieldErrors.email}/><InputField label="Username" required value={form.username} onChange={e=>setForm({...form,username:e.target.value})} hint="3–30 letters, numbers, dots, underscores or hyphens" error={fieldErrors.username}/><InputField label="Temporary password (optional)" type="password" value={form.temporaryPassword} onChange={e=>setForm({...form,temporaryPassword:e.target.value})} hint="Leave blank to generate one securely." error={fieldErrors.temporaryPassword}/><div className="modal-form-footer"><span className="muted-small"><LockKeyhole size={14}/> Must change password at first sign-in</span><div><Button variant="secondary" type="button" onClick={()=>setModal(false)}>Cancel</Button><Button type="submit" loading={saving}>Create HR user</Button></div></div></form></Modal>:null}
 {credential?<Modal title="Temporary credential" subtitle="Copy this password now. For security, it will not be shown again." onClose={()=>setCredential(null)}><div className="credential-card"><div className="credential-symbol"><ShieldCheck size={23}/></div><strong>{credential.name}</strong><span>{credential.email}</span><span>Username: <b>{credential.username}</b></span><div className="credential-value">{credential.password}<CopyValue value={credential.password}/></div><p>Share securely. The user must change this password before normal workspace access.</p><Button block onClick={()=>setCredential(null)}>Done</Button></div></Modal>:null}
 </>;
}

function AttendancePage({user,showToast}) {
 const employeeMode=user.role==='employee';const todayKey=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Karachi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const [items,setItems]=React.useState([]);const [corrections,setCorrections]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [busy,setBusy]=React.useState(false);const [correctionModal,setCorrectionModal]=React.useState(false);const [correctionForm,setCorrectionForm]=React.useState({dayKey:todayKey,reason:'',requestedCheckIn:'',requestedCheckOut:''});
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{if(employeeMode){const result=await api('/attendance/mine');setItems(result.items||[]);}else{const [res,corr]=await Promise.all([api('/attendance?limit=500'),api('/attendance/corrections')]);setItems(res.items||[]);setCorrections(corr.items||[]);}}catch(e){setError(e.message);}finally{setLoading(false);}},[employeeMode]);React.useEffect(()=>{load();},[load]);
 const todayRecord=employeeMode?items.find(a=>a.dayKey===todayKey):null;const checkedIn=Boolean(todayRecord?.checkIn);const checkedOut=Boolean(todayRecord?.checkOut);
 async function checkAction(){setBusy(true);try{const result=await api(`/attendance/${checkedIn?'check-out':'check-in'}`,{method:'POST',body:{}});showToast(result.message||'Attendance updated.');await load();}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
 async function requestCorrection(e){e.preventDefault();setBusy(true);try{const body={dayKey:correctionForm.dayKey,reason:correctionForm.reason};if(correctionForm.requestedCheckIn)body.requestedCheckIn=new Date(correctionForm.requestedCheckIn).toISOString();if(correctionForm.requestedCheckOut)body.requestedCheckOut=new Date(correctionForm.requestedCheckOut).toISOString();await api('/attendance/corrections',{method:'POST',body});showToast('Correction request submitted.');setCorrectionModal(false);setCorrectionForm({dayKey:todayKey,reason:'',requestedCheckIn:'',requestedCheckOut:''});load();}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
 async function decideCorrection(item,status){const comment=window.prompt(`${status==='approved'?'Approval':'Rejection'} comment (optional):`,'');if(comment===null)return;try{await api(`/attendance/corrections/${item._id}/decision`,{method:'PATCH',body:{status,reviewerComment:comment}});showToast(`Correction request ${status}.`);load();}catch(e){showToast(e.message,'error');}}
 const employeeColumns=[{key:'dayKey',label:'Date',render:a=><strong>{dateText(`${a.dayKey}T00:00:00Z`)}</strong>},{key:'checkIn',label:'Check-in',render:a=>timeText(a.checkIn)},{key:'checkOut',label:'Check-out',render:a=>timeText(a.checkOut)},{key:'hoursWorked',label:'Hours',render:a=>a.hoursWorked?`${a.hoursWorked.toFixed(2)} h`:'—'},{key:'status',label:'Status',render:a=><StatusPill status={a.status}/>}];
 const staffColumns=[{key:'employee',label:'Employee',render:a=><div className="person-cell"><Avatar user={a.employee?.user}/><div><strong>{a.employee?.user?.profile?.fullName||'Unknown employee'}</strong><small>{a.employee?.employeeCode||'No employee code'}</small></div></div>},{key:'dayKey',label:'Date',render:a=>dateText(`${a.dayKey}T00:00:00Z`)},{key:'checkIn',label:'Check-in',render:a=>timeText(a.checkIn)},{key:'checkOut',label:'Check-out',render:a=>timeText(a.checkOut)},{key:'hoursWorked',label:'Hours',render:a=>a.hoursWorked?`${a.hoursWorked.toFixed(2)} h`:'—'},{key:'status',label:'Status',render:a=><StatusPill status={a.status}/>}];
 const correctionColumns=[{key:'employee',label:'Employee',render:r=><div className="person-cell"><Avatar user={r.employee?.user}/><div><strong>{r.employee?.user?.profile?.fullName||'Employee'}</strong><small>{r.employee?.employeeCode||''}</small></div></div>},{key:'dayKey',label:'Date',render:r=>dateText(`${r.dayKey}T00:00:00Z`)},{key:'reason',label:'Reason',render:r=><span className="reason-cell">{r.reason}</span>},{key:'requested',label:'Requested times',render:r=><span>{r.requestedCheckIn?timeText(r.requestedCheckIn):'—'} / {r.requestedCheckOut?timeText(r.requestedCheckOut):'—'}</span>},{key:'status',label:'Status',render:r=><StatusPill status={r.status}/>},{key:'actions',label:'',align:'right',render:r=>r.status==='pending'?<div className="row-actions"><button className="icon-button icon-success" title="Approve correction" onClick={()=>decideCorrection(r,'approved')}><CheckCircle2 size={15}/></button><button className="icon-button icon-danger" title="Reject correction" onClick={()=>decideCorrection(r,'rejected')}><XCircle size={15}/></button></div>:<span className="muted-small">Reviewed</span>}];
 return <><PageHeader eyebrow="TIME & ATTENDANCE" title={employeeMode?'My attendance':'Attendance overview'} description={employeeMode?'Record your workday and review your saved attendance history.':'Review recorded check-ins, hours and attendance correction requests.'} actions={employeeMode?<><Button variant="secondary" onClick={()=>setCorrectionModal(true)}><FileText size={15}/> Request correction</Button><Button disabled={checkedOut} loading={busy} onClick={checkAction}>{checkedIn?'Check out':'Check in'} <ArrowUpRight size={15}/></Button></>:<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh records</Button>}/>
 {employeeMode?<div className="attendance-day-card"><div className="attendance-day-date"><span className="day-number">{new Date().getDate()}</span><span>{new Date().toLocaleDateString(undefined,{month:'long',year:'numeric'})}</span></div><div className="attendance-day-status"><span className={`live-mark ${checkedIn&&!checkedOut?'live-mark-on':''}`}/><div><strong>{!todayRecord?'No check-in recorded':checkedOut?'Workday completed':checkedIn?'You are checked in':'No check-in recorded'}</strong><small>{todayRecord?`${timeText(todayRecord.checkIn)} start${todayRecord.checkOut?` · ${timeText(todayRecord.checkOut)} end`:''}`:'Check in when you begin work.'}</small></div></div><div className="attendance-day-hours"><strong>{todayRecord?.hoursWorked?`${todayRecord.hoursWorked.toFixed(2)} h`:'—'}</strong><small>Recorded hours</small></div></div>:<div className="stats-grid compact-stats"><StatCard label="Records in view" value={items.length} icon={Clock3} tone="teal" note="Saved records only"/><StatCard label="Late check-ins" value={items.filter(a=>a.status==='late').length} icon={Activity} tone="amber" note="Current result set"/><StatCard label="Correction requests" value={corrections.filter(c=>c.status==='pending').length} icon={FileText} tone="violet" note="Awaiting review"/><StatCard label="Missing checkout" value={items.filter(a=>a.status==='missing_checkout'||(a.checkIn&&!a.checkOut&&a.dayKey<todayKey)).length} icon={Clock3} tone="blue" note="Needs follow-up"/></div>}
 {error?<ErrorBanner message={error} onRetry={load}/>:null}
 <section className="panel table-panel"><div className="table-toolbar"><div><h2>{employeeMode?'Attendance history':'Recorded attendance'}</h2><p>{employeeMode?'Your saved attendance records for this year.':'Records that have been explicitly saved; no absent records are fabricated.'}</p></div><Button size="sm" variant="secondary" onClick={load}><RefreshCw size={14}/> Refresh</Button></div><Table columns={employeeMode?employeeColumns:staffColumns} rows={items} loading={loading} emptyTitle="No attendance records yet" emptyDescription={employeeMode?'Your first check-in will show up here.':'Records will appear after employees check in or an authorized reviewer records a correction.'} rowKey={r=>r._id}/></section>
 {!employeeMode?<section className="panel table-panel section-gap"><div className="table-toolbar"><div><h2>Correction requests</h2><p>Review requested attendance updates before they change records.</p></div><span className="tag tag-soft">{corrections.filter(c=>c.status==='pending').length} pending</span></div><Table columns={correctionColumns} rows={corrections} emptyTitle="All caught up" emptyDescription="No attendance correction requests are awaiting review." rowKey={r=>r._id}/></section>:null}
 {correctionModal?<Modal title="Request an attendance correction" subtitle="Share the date and reason. An authorized reviewer will approve or reject the request." onClose={()=>setCorrectionModal(false)}><form className="modal-form" onSubmit={requestCorrection}><InputField label="Attendance date" type="date" required value={correctionForm.dayKey} onChange={e=>setCorrectionForm({...correctionForm,dayKey:e.target.value})}/><InputField label="Requested check-in time (optional)" type="datetime-local" value={correctionForm.requestedCheckIn} onChange={e=>setCorrectionForm({...correctionForm,requestedCheckIn:e.target.value})}/><InputField label="Requested check-out time (optional)" type="datetime-local" value={correctionForm.requestedCheckOut} onChange={e=>setCorrectionForm({...correctionForm,requestedCheckOut:e.target.value})}/><TextAreaField label="Reason" required minLength={5} rows={3} placeholder="Explain why this record needs a correction…" value={correctionForm.reason} onChange={e=>setCorrectionForm({...correctionForm,reason:e.target.value})}/><div className="modal-form-footer"><span className="muted-small">Your request will not change attendance until approved.</span><div><Button variant="secondary" type="button" onClick={()=>setCorrectionModal(false)}>Cancel</Button><Button type="submit" loading={busy}>Submit request</Button></div></div></form></Modal>:null}
 </>;
}

function LeavePage({user,showToast}) {
 const employeeMode=user.role==='employee';const [items,setItems]=React.useState([]);const [balances,setBalances]=React.useState({});const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [modal,setModal]=React.useState(false);const [busy,setBusy]=React.useState(false);const [filter,setFilter]=React.useState('pending');const [form,setForm]=React.useState({leaveType:'annual',startDate:'',endDate:'',reason:''});const [naturalText,setNaturalText]=React.useState('');const [aiBusy,setAiBusy]=React.useState(false);
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{if(employeeMode){const res=await api('/leaves/mine');setItems(res.items||[]);setBalances(res.balances||{});}else{const res=await api(`/leaves${filter?`?status=${filter}`:''}`);setItems(res.items||[]);}}catch(e){setError(e.message);}finally{setLoading(false);}},[employeeMode,filter]);React.useEffect(()=>{load();},[load]);
 async function submit(e){e.preventDefault();setBusy(true);try{await api('/leaves',{method:'POST',body:form});showToast('Leave request submitted for review.');setModal(false);setForm({leaveType:'annual',startDate:'',endDate:'',reason:''});load();}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
 async function decide(item,status){const comment=window.prompt(`${status==='approved'?'Approval':'Rejection'} comment (optional):`,'');if(comment===null)return;try{await api(`/leaves/${item._id}/decision`,{method:'PATCH',body:{status,reviewerComment:comment}});showToast(`Leave request ${status}.`);load();}catch(e){showToast(e.message,'error');}}
 async function cancelRequest(item){if(!window.confirm('Cancel this pending leave request?'))return;try{await api(`/leaves/${item._id}/cancel`,{method:'POST',body:{}});showToast('Leave request cancelled.');load();}catch(e){showToast(e.message,'error');}}
 async function parseSmartLeave(e){e.preventDefault();if(!naturalText.trim())return;setAiBusy(true);try{const res=await api('/ai/parse-leave',{method:'POST',body:{text:naturalText}});const obj=res.suggestion;if(obj){setForm(old=>({...old,leaveType:obj.leaveType||old.leaveType,startDate:obj.startDate||old.startDate,endDate:obj.endDate||old.endDate,reason:obj.reason||naturalText}));if(res.warnings?.length)showToast(res.warnings.join(' '),'info');else showToast('AI suggestion prepared. Review every field before submitting.');}else{setForm(old=>({...old,reason:naturalText}));showToast(res.message||'AI could not identify exact dates. Please select the dates and review your reason.','info');}setModal(true);}catch{setForm(old=>({...old,reason:naturalText}));setModal(true);showToast('AI is unavailable. Complete the leave form manually.','info');}finally{setAiBusy(false);}}
 const columns=[{key:'employee',label:'Employee',render:r=><div className="person-cell"><Avatar user={r.employee?.user}/><div><strong>{r.employee?.user?.profile?.fullName||'Employee'}</strong><small>{r.employee?.employeeCode||''}</small></div></div>},{key:'leaveType',label:'Type',render:r=><span className="type-label">{humanize(r.leaveType)}</span>},{key:'dates',label:'Dates',render:r=><div className="stacked-cell"><span>{dateText(r.startDate)} — {dateText(r.endDate)}</span><small>{r.workingDays} working day{r.workingDays===1?'':'s'}</small></div>},{key:'reason',label:'Reason',render:r=><span className="reason-cell">{r.reason}</span>},{key:'status',label:'Status',render:r=><StatusPill status={r.status}/>},{key:'actions',label:'',align:'right',render:r=>r.status==='pending'?<div className="row-actions"><button className="icon-button icon-success" title="Approve request" onClick={()=>decide(r,'approved')}><CheckCircle2 size={15}/></button><button className="icon-button icon-danger" title="Reject request" onClick={()=>decide(r,'rejected')}><XCircle size={15}/></button></div>:<span className="muted-small">{r.reviewerComment||'Reviewed'}</span>}];
 const mineColumns=[{key:'leaveType',label:'Type',render:r=><span className="type-label">{humanize(r.leaveType)}</span>},{key:'dates',label:'Dates',render:r=><div className="stacked-cell"><span>{dateText(r.startDate)} — {dateText(r.endDate)}</span><small>{r.workingDays} working days</small></div>},{key:'reason',label:'Reason',render:r=><span className="reason-cell">{r.reason}</span>},{key:'status',label:'Status',render:r=><StatusPill status={r.status}/>},{key:'createdAt',label:'Applied',render:r=>dateText(r.createdAt)},{key:'actions',label:'',align:'right',render:r=>r.status==='pending'?<button className="icon-button" title="Cancel request" onClick={()=>cancelRequest(r)}><XCircle size={15}/></button>:<span className="muted-small">—</span>}];
 return <><PageHeader eyebrow="TIME OFF" title={employeeMode?'My leave':'Leave management'} description={employeeMode?'Plan time away, review your remaining balance and follow requests.':'Review employee leave requests while keeping balances and calendars consistent.'} actions={employeeMode?<Button onClick={()=>setModal(true)}><Plus size={16}/> Request leave</Button>:<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh</Button>}/>
 {employeeMode?<><div className="leave-balance-cards">{[['annual','Annual leave',14,'teal'],['sick','Sick leave',8,'violet'],['casual','Casual leave',10,'amber'],['unpaid','Unpaid leave',null,'blue']].map(([key,label,def,tone])=>{const balance=balances[key]||{};const quota=balance.quota??def;return <div className="leave-balance-card" key={key}><div className={`leave-card-icon tone-${tone}`}><CalendarDays size={18}/></div><span>{label}</span><strong>{balance.remaining===null?'—':Math.max(0,Number(balance.remaining??quota)||0)}<small>{balance.remaining===null?'flexible':'days left'}</small></strong><div className="progress-track"><span className={`progress-${tone}`} style={{width:quota?`${Math.min(100,(Number(balance.used||0)/quota)*100)}%`:'0%'}}/></div><small className="muted-small">{balance.used??0} used this year</small></div>;})}</div><section className="panel smart-leave-panel"><div className="smart-leave-icon"><Sparkles size={20}/></div><div className="smart-leave-copy"><strong>Need help planning time off?</strong><p>Describe your request in plain language. AI may suggest details, but you review every field and submit the form yourself.</p><form className="smart-leave-form" onSubmit={parseSmartLeave}><input className="input" placeholder="e.g. I need next Monday and Tuesday off for a wedding" value={naturalText} onChange={e=>setNaturalText(e.target.value)}/><Button type="submit" loading={aiBusy} variant="secondary"><Sparkles size={15}/> Suggest</Button></form></div></section></>:<div className="stats-grid compact-stats"><StatCard label="Requests in view" value={items.length} icon={CalendarDays} tone="teal" note="Current filter"/><StatCard label="Pending approval" value={items.filter(r=>r.status==='pending').length} icon={Clock3} tone="amber" note="Needs review"/><StatCard label="Approved" value={items.filter(r=>r.status==='approved').length} icon={CheckCircle2} tone="blue" note="Approved requests"/><StatCard label="Rejected" value={items.filter(r=>r.status==='rejected').length} icon={XCircle} tone="violet" note="Reviewed requests"/></div>}
 {error?<ErrorBanner message={error} onRetry={load}/>:null}<section className="panel table-panel"><div className="table-toolbar"><div><h2>{employeeMode?'Your requests':'Leave requests'}</h2><p>{employeeMode?'Requests from this year and earlier.':'Review pending requests and confirm valid business days.'}</p></div>{!employeeMode?<select className="input filter-select" aria-label="Filter leave requests" value={filter} onChange={e=>setFilter(e.target.value)}><option value="pending">Pending only</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="cancelled">Cancelled</option><option value="">All requests</option></select>:null}</div><Table columns={employeeMode?mineColumns:columns} rows={items} loading={loading} emptyTitle={employeeMode?'No leave requests yet':'No requests for this filter'} emptyDescription={employeeMode?'Apply for leave to start tracking your time off.':'Pending requests will appear when an employee applies for leave.'} rowKey={r=>r._id}/></section>
 {modal?<Modal title="Request time off" subtitle="Working days exclude weekends and configured public holidays. Submission does not mean approval." onClose={()=>setModal(false)}><form className="modal-form" onSubmit={submit}><SelectField label="Leave type" value={form.leaveType} onChange={e=>setForm({...form,leaveType:e.target.value})}><option value="annual">Annual leave</option><option value="sick">Sick leave</option><option value="casual">Casual leave</option><option value="unpaid">Unpaid leave</option><option value="other">Other</option></SelectField><div className="form-grid"><InputField label="Start date" type="date" required value={form.startDate} onChange={e=>setForm({...form,startDate:e.target.value})}/><InputField label="End date" type="date" required value={form.endDate} onChange={e=>setForm({...form,endDate:e.target.value})}/></div><TextAreaField label="Reason" required minLength={5} rows={4} placeholder="Share the reason for your request…" value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})}/><div className="modal-form-footer"><span className="muted-small">Balances and overlaps are checked by the server.</span><div><Button type="button" variant="secondary" onClick={()=>setModal(false)}>Cancel</Button><Button type="submit" loading={busy}>Submit request</Button></div></div></form></Modal>:null}
 </>;
}

function PayrollPage({user,showToast}) {
 const employeeMode=user.role==='employee';const [runs,setRuns]=React.useState([]);const [slips,setSlips]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [period,setPeriod]=React.useState(new Date().toISOString().slice(0,7));const [busy,setBusy]=React.useState(false);const [selectedRun,setSelectedRun]=React.useState('');
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{if(employeeMode){const result=await api('/payroll/mine');setSlips(result.items||[]);}else{const result=await api('/payroll/runs');setRuns(result.items||[]);}}catch(e){setError(e.message);}finally{setLoading(false);}},[employeeMode]);React.useEffect(()=>{load();},[load]);
 async function createDraft(e){e?.preventDefault();setBusy(true);try{const result=await api('/payroll/runs/draft',{method:'POST',body:{period}});showToast(`Payroll draft prepared for ${period}. ${result.payslipsCreated??0} payslips calculated.`);setSelectedRun(result.run?._id||'');load();}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
 async function finalize(run){if(!window.confirm(`Finalize payroll for ${run.period}? This locks the run and makes payslips available to employees. This cannot be undone in the app.`))return;setBusy(true);try{await api(`/payroll/runs/${run._id}/finalize`,{method:'POST',body:{}});showToast(`Payroll ${run.period} finalized and locked.`);load();}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
 async function viewPayslips(run){setSelectedRun(run._id);setLoading(true);try{const res=await api(`/payroll/payslips?period=${run.period}`);setSlips(res.items||[]);}catch(e){showToast(e.message,'error');}finally{setLoading(false);}}
 const runColumns=[{key:'period',label:'Period',render:r=><div className="stacked-cell"><strong>{r.period}</strong><small>Monthly payroll</small></div>},{key:'employeeCount',label:'Employees',align:'right',render:r=>r.summary?.employeeCount??0},{key:'gross',label:'Gross total',align:'right',render:r=>money(r.summary?.grossTotal)},{key:'deductions',label:'Deductions',align:'right',render:r=>money(r.summary?.deductionsTotal)},{key:'net',label:'Net total',align:'right',render:r=><strong>{money(r.summary?.netTotal)}</strong>},{key:'status',label:'Status',render:r=><StatusPill status={r.status}/>},{key:'actions',label:'',align:'right',render:r=><div className="row-actions"><button className="text-action" onClick={()=>viewPayslips(r)}>Payslips <ArrowRight size={13}/></button>{r.status==='draft'&&user.role==='admin'?<button className="icon-button icon-success" title="Finalize payroll" disabled={busy} onClick={()=>finalize(r)}><CheckCircle2 size={15}/></button>:null}</div>}];
 const slipColumns=[{key:'period',label:'Period',render:r=><strong>{r.period}</strong>},{key:'employee',label:'Employee',render:r=><div className="stacked-cell"><span>{r.employee?.employeeCode||'Employee'}</span><small>{r.employee?.user?.profile?.fullName||r.employee?.employeeCode||''}</small></div>},{key:'gross',label:'Gross',align:'right',render:r=>money(r.breakdown?.gross)},{key:'deductions',label:'Deductions',align:'right',render:r=>money(r.breakdown?.deductions)},{key:'net',label:'Net pay',align:'right',render:r=><strong>{money(r.breakdown?.net)}</strong>},{key:'actions',label:'',align:'right',render:r=><Button size="sm" variant="secondary" onClick={()=>downloadFile(`/payroll/payslips/${r._id}/pdf`,`payslip-${r.period}.pdf`).catch(e=>showToast(e.message,'error'))}><Download size={14}/> PDF</Button>}];
 const employeeSlipColumns=[{key:'period',label:'Pay period',render:r=><div className="payslip-period-cell"><span className="payslip-icon"><FileText size={17}/></span><div><strong>{r.period}</strong><small>Finalized payslip</small></div></div>},{key:'gross',label:'Gross salary',align:'right',render:r=>money(r.breakdown?.gross)},{key:'deductions',label:'Total deductions',align:'right',render:r=>money(r.breakdown?.deductions)},{key:'tax',label:'Tax',align:'right',render:r=>money(r.breakdown?.tax)},{key:'net',label:'Net pay',align:'right',render:r=><strong className="payroll-net">{money(r.breakdown?.net)}</strong>},{key:'actions',label:'',align:'right',render:r=><Button size="sm" variant="secondary" onClick={()=>downloadFile(`/payroll/payslips/${r._id}/pdf`,`payslip-${r.period}.pdf`).catch(e=>showToast(e.message,'error'))}><Download size={14}/> Download PDF</Button>}];
 return <><PageHeader eyebrow="PAY & REWARDS" title={employeeMode?'My payslips':'Payroll workspace'} description={employeeMode?'Review your finalized monthly payslips and download a PDF copy.':'Prepare payroll drafts from saved employee, attendance and leave records.'} actions={!employeeMode?<form className="payroll-create-form" onSubmit={createDraft}><input aria-label="Payroll period" type="month" className="input month-input" value={period} onChange={e=>setPeriod(e.target.value)} required/><Button type="submit" loading={busy}><Plus size={15}/> Prepare draft</Button></form>:<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh</Button>}/>
 {employeeMode?<div className="payroll-employee-note"><span className="payroll-highlight-icon"><ShieldCheck size={19}/></span><div><strong>Private and secure</strong><p>Only finalized payroll runs are visible here. If a recent month is missing, contact your HR team.</p></div></div>:<><div className="payroll-rules-strip"><div><span className="rules-strip-icon"><CircleDollarSign size={17}/></span><div><strong>Salary calculation rules</strong><small>HRA 40% + medical 10% of basic · annualized progressive illustrative tax slabs</small></div></div><div><span className="rules-strip-icon"><LockKeyhole size={17}/></span><div><strong>Admin-only finalization</strong><small>Finalized payroll runs are locked against changes</small></div></div></div><div className="notice-row"><InlineNotice tone="info">Draft generation recalculates the selected period from current data. Review totals carefully before finalizing. This assignment’s tax is illustrative, not a payroll tax filing service.</InlineNotice></div></>}
 {error?<ErrorBanner message={error} onRetry={load}/>:null}
 {employeeMode?<section className="panel table-panel"><div className="table-toolbar"><div><h2>Available payslips</h2><p>Finalized monthly salary statements</p></div><span className="tag tag-soft">{slips.length} records</span></div><Table columns={employeeSlipColumns} rows={slips.filter(s=>s.payrollRun)} loading={loading} emptyTitle="No finalized payslips yet" emptyDescription="Your payslips appear after the Admin finalizes a monthly payroll run." rowKey={r=>r._id}/></section>:<><section className="panel table-panel"><div className="table-toolbar"><div><h2>Payroll runs</h2><p>Drafts can be refreshed. Finalized periods are locked.</p></div><span className="tag tag-soft">{runs.length} periods</span></div><Table columns={runColumns} rows={runs} loading={loading} emptyTitle="No payroll runs yet" emptyDescription="Select a month above and prepare a draft based on actual employee records." rowKey={r=>r._id}/></section>{selectedRun?<section className="panel table-panel section-gap"><div className="table-toolbar"><div><h2>Payslips for selected run</h2><p>Detailed breakdown by employee · no sensitive values in AI logs</p></div><button className="icon-button" onClick={()=>setSelectedRun('')} aria-label="Close payslip details"><X size={16}/></button></div><Table columns={slipColumns} rows={slips} loading={loading} emptyTitle="No payslips for this run" emptyDescription="Prepare the draft again to generate payslip calculations." rowKey={r=>r._id}/></section>:null}</>}
 </>;
}

function AnnouncementsPage({user,showToast}) {
 const canPost=user.role==='admin'||user.role==='hr';const [items,setItems]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [modal,setModal]=React.useState(false);const [busy,setBusy]=React.useState(false);const [form,setForm]=React.useState({title:'',body:'',audience:'all'});
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{const res=await api('/announcements');setItems(res.items||[]);}catch(e){setError(e.message);}finally{setLoading(false);}},[]);React.useEffect(()=>{load();},[load]);
 async function submit(e){e.preventDefault();setBusy(true);try{await api('/announcements',{method:'POST',body:form});showToast('Announcement published.');setModal(false);setForm({title:'',body:'',audience:'all'});load();}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
 return <><PageHeader eyebrow="TEAM COMMUNICATION" title="Announcements" description="Keep company updates, reminders and important messages in one place." actions={canPost?<Button onClick={()=>setModal(true)}><Plus size={16}/> New announcement</Button>:<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh</Button>}/>
 {error?<ErrorBanner message={error} onRetry={load}/>:null}
 {loading?<div className="announcement-grid"><div className="skeleton-panel"/><div className="skeleton-panel"/></div>:items.length?<div className="announcement-grid">{items.map((item,index)=><article key={item._id} className={`announcement-card announcement-accent-${index%3}`}><div className="announcement-card-top"><span className="announcement-kicker"><span/> {item.audience==='all'?'COMPANY-WIDE':item.audience==='hr'?'HR TEAM':'EMPLOYEES'}</span><span className="announcement-date">{dateText(item.createdAt)}</span></div><h2>{item.title}</h2><p>{item.body}</p><div className="announcement-card-footer"><Avatar user={{profile:{fullName:item.author?.profile?.fullName||'HCM Lite'}}} size="sm"/><div><strong>{item.author?.profile?.fullName||'HCM Lite'}</strong><small>{item.author?.role==='admin'?'Administrator':'People operations'}</small></div><span className="announcement-kind"><MessageCircle size={14}/> Update</span></div></article>)}</div>:<section className="panel"><EmptyState icon={MessageCircle} title="No announcements yet" description="Company updates and staff messages will appear here when they are published." action={canPost?<Button onClick={()=>setModal(true)}><Plus size={15}/> Publish the first update</Button>:null}/></section>}
 {modal?<Modal title="Create an announcement" subtitle="Write a clear update for the selected audience. Your message will be saved and visible to the appropriate roles." onClose={()=>setModal(false)}><form className="modal-form" onSubmit={submit}><InputField label="Announcement title" required minLength={3} maxLength={160} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/><TextAreaField label="Message" required minLength={3} maxLength={5000} rows={5} value={form.body} onChange={e=>setForm({...form,body:e.target.value})} placeholder="Share the update, important dates or next steps…"/><SelectField label="Audience" value={form.audience} onChange={e=>setForm({...form,audience:e.target.value})}><option value="all">Everyone</option><option value="hr">HR only</option><option value="employee">Employees</option></SelectField><div className="modal-form-footer"><span className="muted-small">Visible to the selected audience after publishing.</span><div><Button type="button" variant="secondary" onClick={()=>setModal(false)}>Cancel</Button><Button type="submit" loading={busy}>Publish announcement</Button></div></div></form></Modal>:null}
 </>;
}

function OrganizationPage({showToast}) {
 const [settings,setSettings]=React.useState(null);const [departments,setDepartments]=React.useState([]);const [holidays,setHolidays]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [saving,setSaving]=React.useState(false);const [departmentModal,setDepartmentModal]=React.useState(false);const [holidayModal,setHolidayModal]=React.useState(false);const [departmentForm,setDepartmentForm]=React.useState({name:'',description:''});const [holidayForm,setHolidayForm]=React.useState({name:'',date:'',notes:''});
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{const [s,d,h]=await Promise.all([api('/company/settings'),api('/company/departments'),api(`/company/holidays?year=${new Date().getFullYear()}`)]);setSettings(s.settings);setDepartments(d.items||[]);setHolidays(h.items||[]);}catch(e){setError(e.message);}finally{setLoading(false);}},[]);React.useEffect(()=>{load();},[load]);
 function set(key,value){setSettings(old=>({...old,[key]:value}));}
 async function saveSettings(e){e.preventDefault();setSaving(true);try{const payload={name:settings.name,address:settings.address,timezone:settings.timezone,officeStart:settings.officeStart,officeEnd:settings.officeEnd,gracePeriodMinutes:Number(settings.gracePeriodMinutes),workingDays:settings.workingDays,geofenceRadiusMeters:Number(settings.geofenceRadiusMeters),policies:settings.policies,leaveQuotas:{annual:Number(settings.leaveQuotas?.annual),sick:Number(settings.leaveQuotas?.sick),casual:Number(settings.leaveQuotas?.casual)}};if(settings.officeLatitude!==null&&settings.officeLatitude!=='')payload.officeLatitude=Number(settings.officeLatitude);if(settings.officeLongitude!==null&&settings.officeLongitude!=='')payload.officeLongitude=Number(settings.officeLongitude);const result=await api('/company/settings',{method:'PATCH',body:payload});setSettings(result.settings);showToast('Company settings saved.');}catch(e){showToast(e.message,'error');}finally{setSaving(false);}}
 async function addDepartment(e){e.preventDefault();try{await api('/company/departments',{method:'POST',body:departmentForm});setDepartmentModal(false);setDepartmentForm({name:'',description:''});showToast('Department created.');load();}catch(e){showToast(e.message,'error');}}
 async function addHoliday(e){e.preventDefault();try{await api('/company/holidays',{method:'POST',body:holidayForm});setHolidayModal(false);setHolidayForm({name:'',date:'',notes:''});showToast('Public holiday added.');load();}catch(e){showToast(e.message,'error');}}
 const dayNames=[['Sunday',0],['Monday',1],['Tuesday',2],['Wednesday',3],['Thursday',4],['Friday',5],['Saturday',6]];
 if(loading&&!settings)return <><PageHeader eyebrow="ORGANIZATION" title="Company settings" description="Configure the rules that support your people workflows."/><DashboardSkeleton/></>;
 return <><PageHeader eyebrow="ORGANIZATION" title="Company settings" description="Configure the rules that support your people workflows." actions={<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh</Button>}/>{error?<ErrorBanner message={error} onRetry={load}/>:null}
 <form onSubmit={saveSettings} className="organization-layout"><section className="panel organization-main"><div className="panel-heading"><div><h2>Company details</h2><p>Identity, time zone and office schedule</p></div><span className="panel-heading-icon"><Settings2 size={17}/></span></div><div className="form-grid"><InputField label="Company name" required value={settings?.name||''} onChange={e=>set('name',e.target.value)}/><InputField label="Time zone" required value={settings?.timezone||''} onChange={e=>set('timezone',e.target.value)} hint="e.g. Asia/Karachi"/><InputField label="Office start" type="time" required value={settings?.officeStart||'09:00'} onChange={e=>set('officeStart',e.target.value)}/><InputField label="Office end" type="time" required value={settings?.officeEnd||'17:00'} onChange={e=>set('officeEnd',e.target.value)}/><InputField label="Grace period (minutes)" type="number" min="0" max="180" value={settings?.gracePeriodMinutes??15} onChange={e=>set('gracePeriodMinutes',e.target.value)}/><InputField label="Geofence radius (metres)" type="number" min="10" value={settings?.geofenceRadiusMeters??100} onChange={e=>set('geofenceRadiusMeters',e.target.value)}/></div><TextAreaField label="Company address" rows={2} value={settings?.address||''} onChange={e=>set('address',e.target.value)}/><TextAreaField label="Company policies" rows={4} value={settings?.policies||''} onChange={e=>set('policies',e.target.value)} placeholder="Add policy details the AI assistant can refer to…"/><div className="field"><span className="field-label">Working days</span><div className="weekday-picker">{dayNames.map(([name,value])=><label key={value} className={`weekday-option ${(settings?.workingDays||[]).includes(value)?'selected':''}`}><input type="checkbox" checked={(settings?.workingDays||[]).includes(value)} onChange={e=>set('workingDays',e.target.checked?[...(settings?.workingDays||[]),value].sort():settings.workingDays.filter(v=>v!==value))}/><span>{name.slice(0,3)}</span></label>)}</div><span className="field-hint">These rules affect new attendance and leave calculations; historical records remain unchanged.</span></div><div className="organization-save-row"><span className="muted-small"><ShieldCheck size={14}/> Only Admin can change company-wide rules.</span><Button type="submit" loading={saving}>Save settings <Check size={15}/></Button></div></section>
 <aside className="organization-aside"><section className="panel aside-panel"><div className="panel-heading"><div><h2>Leave quotas</h2><p>Default yearly allowances in days</p></div><CalendarDays size={17}/></div><InputField label="Annual leave" type="number" min="0" value={settings?.leaveQuotas?.annual??14} onChange={e=>set('leaveQuotas',{...settings.leaveQuotas,annual:Number(e.target.value)})}/><InputField label="Sick leave" type="number" min="0" value={settings?.leaveQuotas?.sick??8} onChange={e=>set('leaveQuotas',{...settings.leaveQuotas,sick:Number(e.target.value)})}/><InputField label="Casual leave" type="number" min="0" value={settings?.leaveQuotas?.casual??10} onChange={e=>set('leaveQuotas',{...settings.leaveQuotas,casual:Number(e.target.value)})}/></section>
 <section className="panel aside-panel"><div className="panel-heading"><div><h2>Departments</h2><p>{departments.length} active units</p></div><button className="icon-button" onClick={()=>setDepartmentModal(true)} title="Add department"><Plus size={16}/></button></div>{departments.length?<div className="department-list">{departments.map(d=><div className="department-row" key={d._id}><span className="department-avatar">{initials(d.name)}</span><span><strong>{d.name}</strong><small>{d.description||'No description'}</small></span><span className="department-count"><Users size={13}/></span></div>)}</div>:<EmptyState icon={Users} title="No departments" description="Add a department to organize employees."/>}<Button variant="secondary" block onClick={()=>setDepartmentModal(true)}><Plus size={14}/> Add department</Button></section>
 <section className="panel aside-panel"><div className="panel-heading"><div><h2>Public holidays</h2><p>{new Date().getFullYear()} calendar</p></div><button className="icon-button" onClick={()=>setHolidayModal(true)} title="Add holiday"><Plus size={16}/></button></div>{holidays.length?<div className="holiday-list">{holidays.map(h=><div className="holiday-row" key={h._id}><span className="holiday-date"><strong>{new Date(h.date).getUTCDate()}</strong><small>{new Date(h.date).toLocaleDateString(undefined,{month:'short',timeZone:'UTC'})}</small></span><span><strong>{h.name}</strong><small>{h.notes||'Public holiday'}</small></span></div>)}</div>:<p className="muted-small empty-small">No public holidays configured for this year.</p>}<Button variant="secondary" block onClick={()=>setHolidayModal(true)}><Plus size={14}/> Add public holiday</Button></section></aside></form>
 {departmentModal?<Modal title="Add department" onClose={()=>setDepartmentModal(false)}><form className="modal-form" onSubmit={addDepartment}><InputField label="Department name" required value={departmentForm.name} onChange={e=>setDepartmentForm({...departmentForm,name:e.target.value})}/><TextAreaField label="Description (optional)" rows={3} value={departmentForm.description} onChange={e=>setDepartmentForm({...departmentForm,description:e.target.value})}/><div className="modal-form-footer"><span/><div><Button variant="secondary" type="button" onClick={()=>setDepartmentModal(false)}>Cancel</Button><Button type="submit">Create department</Button></div></div></form></Modal>:null}
 {holidayModal?<Modal title="Add public holiday" onClose={()=>setHolidayModal(false)}><form className="modal-form" onSubmit={addHoliday}><InputField label="Holiday name" required value={holidayForm.name} onChange={e=>setHolidayForm({...holidayForm,name:e.target.value})}/><InputField label="Date" type="date" required value={holidayForm.date} onChange={e=>setHolidayForm({...holidayForm,date:e.target.value})}/><TextAreaField label="Notes (optional)" rows={2} value={holidayForm.notes} onChange={e=>setHolidayForm({...holidayForm,notes:e.target.value})}/><div className="modal-form-footer"><span/><div><Button variant="secondary" type="button" onClick={()=>setHolidayModal(false)}>Cancel</Button><Button type="submit">Add holiday</Button></div></div></form></Modal>:null}
 </>;
}

function ProfilePage({user,onUserUpdate,showToast}) {
 const [profile,setProfile]=React.useState({user,employee:null,notifications:[]});const [loading,setLoading]=React.useState(true);const [saving,setSaving]=React.useState(false);const [error,setError]=React.useState('');const [form,setForm]=React.useState({fullName:user.profile?.fullName||'',phone:user.profile?.phone||'',address:user.profile?.address||''});const [file,setFile]=React.useState(null);const [preview,setPreview]=React.useState('');const [uploadBusy,setUploadBusy]=React.useState(false);const [removeBusy,setRemoveBusy]=React.useState(false);
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{const result=await api('/profile');setProfile(result);const p=result.user?.profile||{};setForm({fullName:p.fullName||'',phone:p.phone||'',address:p.address||''});}catch(e){setError(e.message);}finally{setLoading(false);}},[]);React.useEffect(()=>{load();},[load]);React.useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview);},[preview]);
 async function save(e){e.preventDefault();setSaving(true);try{const body={phone:form.phone,address:form.address};if(user.role!=='employee')body.fullName=form.fullName;const result=await api('/profile',{method:'PATCH',body});setProfile(old=>({...old,user:result.user}));onUserUpdate(result.user);showToast('Profile details saved.');}catch(e){showToast(e.message,'error');}finally{setSaving(false);}}
 function chooseFile(e){const chosen=e.target.files?.[0];if(!chosen)return;if(!['image/jpeg','image/png','image/webp'].includes(chosen.type)){showToast('Choose a JPG, PNG, or WebP image.','error');e.target.value='';return;}if(chosen.size>5*1024*1024){showToast('Image must be 5 MB or smaller.','error');e.target.value='';return;}if(preview)URL.revokeObjectURL(preview);setFile(chosen);setPreview(URL.createObjectURL(chosen));}
 async function upload(){if(!file)return;setUploadBusy(true);try{const data=new FormData();data.append('avatar',file);const result=await api('/profile/avatar',{method:'POST',body:data});setProfile(old=>({...old,user:result.user}));onUserUpdate(result.user);setFile(null);if(preview)URL.revokeObjectURL(preview);setPreview('');showToast('Profile picture updated.');}catch(e){showToast(e.message,'error');}finally{setUploadBusy(false);}}
 async function removeAvatar(){if(!window.confirm('Remove your current profile picture?'))return;setRemoveBusy(true);try{const result=await api('/profile/avatar',{method:'DELETE'});setProfile(old=>({...old,user:result.user}));onUserUpdate(result.user);setFile(null);if(preview)URL.revokeObjectURL(preview);setPreview('');showToast('Profile picture removed.');}catch(e){showToast(e.message,'error');}finally{setRemoveBusy(false);}}
 async function markRead(item){try{await api(`/profile/notifications/${item._id}/read`,{method:'PATCH',body:{}});setProfile(old=>({...old,notifications:old.notifications.map(n=>n._id===item._id?{...n,readAt:new Date().toISOString()}:n)}));}catch(e){showToast(e.message,'error');}}
 const displayedUser=profile.user||user;
 return <><PageHeader eyebrow="ACCOUNT" title="My profile" description="Keep your contact details and profile picture up to date." actions={<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh profile</Button>}/>{error?<ErrorBanner message={error} onRetry={load}/>:null}
 {loading?<DashboardSkeleton/>:<div className="profile-layout"><div className="profile-main-column"><section className="panel profile-hero-card"><div className="profile-cover"><span>HCM LITE · PEOPLE</span><div className="cover-decoration cover-decoration-one"/><div className="cover-decoration cover-decoration-two"/></div><div className="profile-hero-content"><div className="profile-avatar-wrap"><div className="profile-avatar-large">{preview?<img src={preview} alt="Selected profile preview"/>:displayedUser.profile?.avatarUrl?<img src={displayedUser.profile.avatarUrl} alt="Profile"/>:<span>{initials(displayedUser.profile?.fullName||displayedUser.username)}</span>}</div><label className="avatar-change-button" title="Choose profile picture"><ImagePlus size={16}/><input type="file" accept="image/png,image/jpeg,image/webp" onChange={chooseFile} aria-label="Choose profile picture"/></label></div><div className="profile-hero-name"><h2>{displayedUser.profile?.fullName||displayedUser.username}</h2><p>{displayedUser.email}</p><div className="profile-badges"><span className="role-badge"><ShieldCheck size={13}/>{displayedUser.role==='admin'?'Administrator':displayedUser.role==='hr'?'Human resources':'Employee self-service'}</span><StatusPill status={displayedUser.active?'active':'inactive'}/></div></div><div className="profile-hero-actions">{file?<><Button size="sm" loading={uploadBusy} onClick={upload}><Check size={14}/> Save photo</Button><Button size="sm" variant="secondary" onClick={()=>{setFile(null);if(preview)URL.revokeObjectURL(preview);setPreview('');}}>Cancel</Button></>:displayedUser.profile?.avatarUrl?<Button size="sm" variant="secondary" loading={removeBusy} onClick={removeAvatar}><Trash2 size={14}/> Remove photo</Button>:<span className="muted-small">Add a profile picture</span>}</div></div><div className="profile-picture-help"><InfoIcon/> JPG, PNG or WebP · maximum 5 MB · uploaded securely</div></section>
 <section className="panel profile-details-panel"><div className="panel-heading"><div><h2>Personal information</h2><p>Only fields you are allowed to edit can be changed here.</p></div><span className="panel-heading-icon"><UserRound size={17}/></span></div><form className="modal-form" onSubmit={save}><div className="form-grid"><InputField label="Full name" value={form.fullName} disabled={user.role==='employee'} onChange={e=>setForm({...form,fullName:e.target.value})} hint={user.role==='employee'?'Contact HR to change your registered name.':undefined}/><InputField label="Email address" value={displayedUser.email||''} disabled/><InputField label="Username" value={displayedUser.username||''} disabled/><InputField label="Phone number" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></div><TextAreaField label="Address" rows={3} value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/><div className="modal-form-footer"><span className="muted-small">Account email, username and role are managed by authorized staff.</span><Button type="submit" loading={saving}>Save changes <Check size={15}/></Button></div></form></section>
 {profile.employee?<section className="panel profile-details-panel"><div className="panel-heading"><div><h2>Employment details</h2><p>Read-only information from your employee record</p></div><span className="panel-heading-icon"><Users size={17}/></span></div><div className="employment-details-grid"><div><span>Employee code</span><strong>{profile.employee.employeeCode}</strong></div><div><span>Department</span><strong>{profile.employee.department?.name||'Unassigned'}</strong></div><div><span>Designation</span><strong>{profile.employee.designation||'Not set'}</strong></div><div><span>Joining date</span><strong>{dateText(profile.employee.joiningDate)}</strong></div><div><span>Employment status</span><strong><StatusPill status={profile.employee.employmentStatus}/></strong></div></div></section>:null}</div>
 <aside className="profile-side-column"><section className="panel profile-account-panel"><div className="panel-heading"><div><h2>Account status</h2><p>Security and access</p></div><ShieldCheck size={17}/></div><div className="account-status-row"><span className="account-status-icon"><CheckCircle2 size={18}/></span><div><strong>Account is {displayedUser.active?'active':'inactive'}</strong><small>Role: {displayedUser.role}</small></div></div><div className="account-info-row"><span>Last login</span><strong>{displayedUser.lastLoginAt?`${dateText(displayedUser.lastLoginAt)} ${timeText(displayedUser.lastLoginAt)}`:'Not recorded'}</strong></div><div className="account-info-row"><span>Member since</span><strong>{dateText(displayedUser.createdAt)}</strong></div><div className="account-info-row"><span>Session security</span><strong><span className="secure-green-dot"/> HttpOnly cookie</strong></div></section>
 <section className="panel profile-notifications-panel"><div className="panel-heading"><div><h2>Notifications</h2><p>Recent updates for your account</p></div><span className="notification-count">{(profile.notifications||[]).filter(n=>!n.readAt).length}</span></div>{profile.notifications?.length?<div className="profile-notification-list">{profile.notifications.slice(0,8).map(n=><div className={`profile-notification ${n.readAt?'is-read':''}`} key={n._id}><span className="notification-dot"/><div><strong>{n.title}</strong><p>{n.message}</p><small>{relativeDate(n.createdAt)}</small></div>{!n.readAt?<button className="icon-button" title="Mark as read" onClick={()=>markRead(n)}><CheckCheck size={14}/></button>:null}</div>)}</div>:<EmptyState icon={Bell} title="All quiet here" description="Leave decisions and payslip updates will show here."/>}</section></aside></div>}
 </>;
}
function InfoIcon(){return <span className="info-icon-small">i</span>}

function AuditPage() {
 const [items,setItems]=React.useState([]);const [loading,setLoading]=React.useState(true);const [error,setError]=React.useState('');const [filter,setFilter]=React.useState('');
 const load=React.useCallback(async()=>{setLoading(true);setError('');try{const result=await api(`/audit?limit=100${filter?`&action=${encodeURIComponent(filter)}`:''}`);setItems(result.items||[]);}catch(e){setError(e.message);}finally{setLoading(false);}},[filter]);React.useEffect(()=>{load();},[load]);
 const columns=[{key:'createdAt',label:'Time',render:r=><div className="stacked-cell"><strong>{dateText(r.createdAt)}</strong><small>{timeText(r.createdAt)}</small></div>},{key:'actor',label:'Actor',render:r=><div className="person-cell"><Avatar user={r.actor}/><div><strong>{r.actor?.profile?.fullName||'System'}</strong><small>{r.actor?.role||r.actorRole||'system'}</small></div></div>},{key:'action',label:'Action',render:r=><span className="audit-action-label">{humanize(r.action)}</span>},{key:'entity',label:'Entity',render:r=><div className="stacked-cell"><span>{r.entity}</span><small>{r.entityId?String(r.entityId).slice(-9):'—'}</small></div>},{key:'ip',label:'Source',render:r=><span className="code-chip">{r.ip||'Internal'}</span>}];
 return <><PageHeader eyebrow="SECURITY & COMPLIANCE" title="Audit trail" description="Append-only history of important administrative and business actions." actions={<Button variant="secondary" onClick={load}><RefreshCw size={15}/> Refresh log</Button>}/><div className="audit-notice"><span><ShieldCheck size={18}/></span><div><strong>Read-only by design</strong><p>Audit entries cannot be edited or deleted through the application. Passwords, tokens and provider secrets are not included in audit snapshots.</p></div></div><section className="panel table-panel"><div className="table-toolbar"><div><h2>Recorded activity</h2><p>Newest entries first</p></div><div className="toolbar-controls"><SearchBox value={filter} onChange={setFilter} placeholder="Filter action name…"/><button className="icon-button" onClick={load} title="Refresh"><RefreshCw size={16}/></button></div></div>{error?<ErrorBanner message={error} onRetry={load}/>:null}<Table columns={columns} rows={items} loading={loading} emptyTitle="No audit entries found" emptyDescription={filter?'Try a broader action filter.':'Important actions will be recorded here as the workspace is used.'} rowKey={r=>r._id}/></section></>;
}

function AIPage({user,showToast}) {
 const initial=[{role:'assistant',content:`Hello ${firstName(user)}. I'm the HCM Lite assistant. I can explain company policies and help you understand the records you're permitted to access. I only use available workspace data, and I cannot approve requests or change records.`}];
 const [messages,setMessages]=React.useState(initial);const [input,setInput]=React.useState('');const [loading,setLoading]=React.useState(false);const [error,setError]=React.useState('');const bottomRef=React.useRef(null);
 React.useEffect(()=>{bottomRef.current?.scrollIntoView({behavior:'smooth',block:'end'});},[messages,loading]);
 const suggestions=user.role==='employee'?['What is my leave balance?','How do I request an attendance correction?','What should I know about my payslips?']:['Summarize current headcount by department.','How many leave requests are pending?','Summarize the latest finalized payroll.'];
 async function send(text=input){const question=String(text||'').trim();if(!question||loading)return;setInput('');setError('');setMessages(old=>[...old,{role:'user',content:question}]);setLoading(true);try{const result=await api('/ai/chat',{method:'POST',body:{message:question}});setMessages(old=>[...old,{role:'assistant',content:result.answer||'No answer was returned.',generatedByAI:Boolean(result.generatedByAI),toolsUsed:result.toolsUsed||[]}]);}catch(e){setError(e.message);setMessages(old=>[...old,{role:'assistant',content:'I could not complete that request just now. Your saved HR records are unchanged. Please try again or use the relevant HR module directly.',generatedByAI:false}]);}finally{setLoading(false);}}
 return <><PageHeader eyebrow="YOUR WORKPLACE ASSISTANT" title="AI assistant" description="Ask questions about available HR information with role-aware access controls." actions={<span className="ai-security-tag"><ShieldCheck size={14}/> Permission-aware</span>}/><div className="ai-layout"><aside className="ai-context-panel"><div className="ai-visual"><div className="ai-orbit ai-orbit-one"/><div className="ai-orbit ai-orbit-two"/><span><Bot size={29}/></span><i className="ai-spark spark-a">✦</i><i className="ai-spark spark-b">✧</i></div><div className="eyebrow">HCM LITE AI</div><h2>Helpful answers.<br/><em>Grounded in your data.</em></h2><p>Your assistant respects your current role and queries approved backend services rather than connecting to the database directly.</p><div className="ai-context-list"><div><span><ShieldCheck size={15}/></span><div><strong>Scoped access</strong><small>{user.role==='employee'?'Only your own personal records and public policies.':user.role==='hr'?'Employee operations and approved HR summaries.':'Company metrics, approved employee data and audit-safe summaries.'}</small></div></div><div><span><Activity size={15}/></span><div><strong>No invented metrics</strong><small>If a relevant record isn't available, the assistant should say so.</small></div></div><div><span><LockKeyhole size={15}/></span><div><strong>No automatic actions</strong><small>Approvals and changes stay in the normal HR workflows.</small></div></div></div><div className="ai-role-card"><Avatar user={user} size="sm"/><div><strong>{user.profile?.fullName||user.username}</strong><small>{user.role==='admin'?'Admin access':user.role==='hr'?'HR access':'Employee access'} · verified session</small></div><CheckCircle2 size={16}/></div></aside><section className="panel ai-chat-panel"><div className="ai-chat-header"><div className="ai-chat-icon"><Bot size={19}/></div><div><strong>HCM assistant</strong><span><i/> Ready to help</span></div><span className="ai-preview-label">AI-GENERATED WHEN AVAILABLE</span></div><div className="ai-chat-messages" aria-live="polite">{messages.map((m,index)=><div key={index} className={`chat-message ${m.role==='user'?'chat-user':'chat-assistant'}`}>{m.role==='assistant'?<span className="chat-avatar"><Bot size={16}/></span>:null}<div className="chat-bubble"><p>{m.content}</p>{m.role==='assistant'?<div className="chat-message-meta">{m.generatedByAI?<span><Sparkles size={12}/> AI-generated</span>:<span><InfoIcon/> Workspace fallback</span>}{m.toolsUsed?.length?<span>· Used saved workspace data</span>:null}</div>:null}</div></div>)}{loading?<div className="chat-message chat-assistant"><span className="chat-avatar"><Bot size={16}/></span><div className="chat-bubble typing-bubble"><span/><span/><span/></div></div>:null}<div ref={bottomRef}/></div>{messages.length===1?<div className="ai-suggestions"><span>TRY ASKING</span>{suggestions.map(s=><button key={s} onClick={()=>send(s)}>{s}<ArrowUpRight size={13}/></button>)}</div>:null}<form className="ai-chat-composer" onSubmit={e=>{e.preventDefault();send();}}><input aria-label="Ask HCM assistant" value={input} onChange={e=>setInput(e.target.value)} placeholder="Ask a question about your workspace…" maxLength={2000} disabled={loading}/><button type="submit" disabled={loading||!input.trim()} aria-label="Send message">{loading?<LoaderCircle size={17} className="spin"/>:<Send size={17}/>}</button></form><div className="ai-chat-footnote"><ShieldCheck size={13}/> Responses depend on data available to your role. Always verify important payroll or policy decisions.</div>{error?<div className="ai-error-footer">{error}</div>:null}</section></div></>;
}
